import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Home from "./Component/Home";
import FindJob from "./Component/FindJob";
import JobDetails from "./Component/JobDetails";
import MyApplications from "./Component/MyApplications";
import StudentLogin from "./Component/StudentLogin";
import StudentRegister from "./Component/StudentRegister";
import CompanyLogin from "./Component/CompanyLogin";
import CompanyRegister from "./Component/CompanyRegister";
import PostJob from "./Component/PostJob";
import ApplicantsList from "./Component/ApplicantsList";
import Payment from "./Component/Payment";
import About from "./Component/About";

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/findjob" element={<FindJob />} />
        <Route path="/jobdetails" element={<JobDetails />} />
        <Route path="/applications" element={<MyApplications />} />
        <Route path="/studentlogin" element={<StudentLogin />} />
        <Route path="/studentregister" element={<StudentRegister />} />
        <Route path="/companylogin" element={<CompanyLogin />} />
        <Route path="/companyregister" element={<CompanyRegister />} />
        <Route path="/postjob" element={<PostJob />} />
        <Route path="/applicants" element={<ApplicantsList />} />
        <Route path="/payment" element={<Payment />} />
        <Route path="/about" element={<About />} />
      </Routes>
    </Router>
  );
}

export default App;
